                          "subtract_v1",
                          "multiply_v1",
                          "divide_v1"
                        ]
                      },
                      "operands": {
                        "type": "array",
                        "minItems": 2,
                        "maxItems": 2,
                        "items": {
                          "type": "string",
                          "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                        }
                      },
                      "rounding": {
                        "type": "string",
                        "enum": [
                          "exact",
                          "half_away_6"
                        ]
                      }
                    },
                    "required": [
                      "id",
                      "role",
                      "operation",
                      "operands",
                      "rounding"
                    ]
                  },
                  {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                      "id": {
                        "type": "string",
                        "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                      },
                      "role": {
                        "type": "string",
                        "enum": [
