                      "reason"
                    ]
                  }
                ]
              }
            },
            "bindings": {
              "type": "array",
              "minItems": 0,
              "maxItems": 8192,
              "items": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                  "path": {
                    "type": "string",
                    "maxLength": 240,
                    "description": "Exact slash-separated recipe path using stable IDs, e.g. definitions/side/x_mm or instances/left/placement/rz. Use no dot notation or array positions. Bind every controlling numeric field, including zero coordinates and rotations."
                  },
                  "node": {
                    "type": "string",
                    "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                  }
                },
                "required": [
                  "path",
                  "node"
                ]
              }
            }
          }
        },
        "remove": {
